def _causal_occurrence_counts(history):
    seen = defaultdict(int)
    counts = []
    for item in history:
        if item != 0:
            seen[item] += 1
            counts.append(seen[item])
        else:
            counts.append(0)
    return counts


def _history_counts_to_tensor(history, maxlen, device):
    counts = _causal_occurrence_counts(history)[-maxlen:]
    padded = [0] * (maxlen - len(counts)) + counts
    return torch.tensor([padded], dtype=torch.float32, device=device)


