def input_embeddings(self, seq: torch.Tensor, occurrence_counts: torch.Tensor) -> torch.Tensor:
    emb = self.item_emb(seq)
    scale = occurrence_counts.to(emb.dtype).clamp_min(1).rsqrt()
    return self.dropout(emb * scale.unsqueeze(-1))

